import {redirect} from 'react-router';
import {validatePreviewUrl} from '@sanity/preview-url-secret';
import type {Route} from './+types/api.preview-mode.enable';
import {createSanityClient, getPreviewCookie} from '~/lib/sanity.server';

/**
 * Called by the Sanity Presentation tool when it loads the storefront in its
 * iframe. Validates the one-time secret generated by the Studio and turns on
 * draft mode for this browser.
 */
export async function loader({request, context}: Route.LoaderArgs) {
  const {env} = context;
  const client = createSanityClient(env);

  if (!client || !env.SANITY_API_READ_TOKEN) {
    throw new Response('Sanity preview is not configured', {status: 500});
  }

  const {isValid, redirectTo = '/'} = await validatePreviewUrl(
    client.withConfig({token: env.SANITY_API_READ_TOKEN, useCdn: false}),
    request.url,
  );

  if (!isValid) {
    throw new Response('Invalid preview secret', {status: 401});
  }

  return redirect(redirectTo, {
    headers: {'Set-Cookie': await getPreviewCookie(env).serialize(true)},
  });
}
